<?php
require_once __DIR__.'/includes/permissions.php';
require_role('buyer');$page_title='Carrinho';$s=db()->prepare('SELECT ci.*,p.name,p.price,p.unit,p.main_image,p.stock,u.name farmer_name FROM cart_items ci JOIN carts c ON c.id=ci.cart_id JOIN products p ON p.id=ci.product_id JOIN farmers f ON f.id=p.farmer_id JOIN users u ON u.id=f.user_id WHERE c.buyer_id=? ORDER BY ci.id');$s->execute([user()['buyer_id']]);$items=$s->fetchAll();$subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$items));include __DIR__.'/includes/header.php';
?><section class="container py-5"><div class="page-title-row"><div><span class="eyebrow">A sua seleção</span><h1>Carrinho</h1></div><a href="<?=base_path('marketplace.php')?>" class="btn btn-outline-primary">Continuar a comprar</a></div><?php if(!$items): ?><div class="empty-state"><i class="bi bi-bag display-3"></i><h3>O seu carrinho está vazio</h3><p class="text-muted">Encontre produtos frescos diretamente dos agricultores.</p><a class="btn btn-primary" href="<?=base_path('marketplace.php')?>">Explorar produtos</a></div><?php else: ?><div class="row g-4"><div class="col-lg-8"><div class="content-card p-0 overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0 cart-table"><thead><tr><th>Produto</th><th>Preço</th><th>Quantidade</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($items as $i): ?><tr data-cart-row="<?=$i['product_id']?>"><td><div class="cart-product"><img src="<?=e(get_product_image($i['main_image']))?>" onerror="this.src='<?=asset('img/product-placeholder.svg')?>'"><div><strong><?=e($i['name'])?></strong><small><?=e($i['farmer_name'])?></small></div></div></td><td><?=money($i['price'])?>/<?=e($i['unit'])?></td><td><div class="mini-qty"><button data-cart-action="decrease" data-product="<?=$i['product_id']?>">−</button><span><?=e($i['quantity'])?></span><button data-cart-action="increase" data-product="<?=$i['product_id']?>">+</button></div></td><td class="fw-bold"><?=money($i['price']*$i['quantity'])?></td><td><button class="btn btn-sm btn-link text-danger" data-cart-action="remove" data-product="<?=$i['product_id']?>"><i class="bi bi-trash"></i></button></td></tr><?php endforeach; ?></tbody></table></div><div class="p-3 border-top text-end"><button class="btn btn-link text-danger" data-cart-action="clear">Limpar carrinho</button></div></div></div><div class="col-lg-4"><div class="summary-card"><h4>Resumo do pedido</h4><div class="summary-line"><span>Subtotal</span><strong><?=money($subtotal)?></strong></div><div class="summary-line"><span>Entrega</span><strong class="text-success">A calcular</strong></div><hr><div class="summary-line total"><span>Total estimado</span><strong><?=money($subtotal)?></strong></div><a href="<?=base_path('checkout.php')?>" class="btn btn-primary w-100 mt-4">Finalizar pedido <i class="bi bi-arrow-right ms-2"></i></a><p class="small text-muted mt-3 mb-0"><i class="bi bi-shield-check me-1"></i> Compra protegida e acompanhamento do pedido.</p></div></div></div><?php endif; ?></section><?php include __DIR__.'/includes/footer.php'; ?>
